/**
 * @brief Standard constructor.
 *
 * @param parent Owning Qt widget
 * @param lower_bound Initial lower bound (Nm)
 * @param upper_bound Initial upper bound (Nm)
 */
ReactiveCwDialog::ReactiveCwDialog(QWidget* parent, const double& lower_bound,
                                   const double& upper_bound)
    : QDialog(parent), ui_(new Ui::ReactiveCwDialog) {
    ui_->setupUi(this);
    this->setModal(true);

    // Populate dialog elements
    ui_->sb_lower_bound->setValue(lower_bound);
    ui_->sb_upper_bound->setValue(upper_bound);
}

/**
 * @brief Standard destructor.
 */
ReactiveCwDialog::~ReactiveCwDialog() {
    delete ui_;
}

//------------------------------------------------------------------------------
// !Class Helpers
//------------------------------------------------------------------------------

/**
 * @brief Gets the lower bound (Nm).
 */
double ReactiveCwDialog::GetLowerBound() const {
    return ui_->sb_lower_bound->value();
}

/**
 * @brief Gets the upper bound (Nm).
 */
double ReactiveCwDialog::GetUpperBound() const {
    return ui_->sb_upper_bound->value();
}

